const corpus = $('Corpus').all();
const judges = $input.all();
return judges.map((it, i) => {
  const c = (corpus[i] && corpus[i].json) || {};
  const got = it.json.verdict;
  const match = (c.expected === 'request-changes') === (got === 'request-changes');
  return { json: { id: c.id, expected: c.expected, got, match } };
});

const rows = $input.all().map((i) => i.json);
let tp = 0, fp = 0, fn = 0, tn = 0;
for (const r of rows) {
  const expPos = r.expected === 'request-changes';
  const gotPos = r.got === 'request-changes';
  if (expPos && gotPos) tp++; else if (!expPos && gotPos) fp++; else if (expPos && !gotPos) fn++; else tn++;
}
const precision = (tp + fp) ? tp / (tp + fp) : null;
const recall = (tp + fn) ? tp / (tp + fn) : null;
const agree = rows.filter((r) => r.match).length;
console.log('CALIBRATION: n=' + rows.length + ' tp=' + tp + ' fp=' + fp + ' fn=' + fn + ' tn=' + tn + ' precision=' + precision + ' recall=' + recall + ' agreement=' + agree + '/' + rows.length);
for (const r of rows) console.log('  ' + r.id + ': expected=' + r.expected + ' got=' + r.got + (r.match ? '' : '  <-- MISS'));
return [{ json: { n: rows.length, tp, fp, fn, tn, precision, recall, agreement: agree, rows } }];
